using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;

namespace VSCore;

/// <summary>
/// Real block colours from the game assets: block code -> average colour of its texture (top view).
///
/// The table (<c>BlockColors.txt</c>, an embedded resource) is generated by the script
/// <c>tools/gen_block_colors.py</c> from blocktypes/*.json and the textures of an installed Vintage Story.
/// The colour is not an "average over the texture": the game takes AvgColor as the average of four pixels
/// (35%/65% along both axes). Blocks with a grass overlay (BlockSoil/BlockSoilDeposit/
/// BlockForestFloor) have a composite colour: the base (`up`) + a tintable grass layer, see
/// <see cref="BlockMapInfo.GrassBase"/>; for the rest — the top face (`up`), otherwise `all`.
/// Blocks with climatic/seasonal tinting are in the table as well: their average colour is the base to which
/// the renderer applies a LUT (see <see cref="MapTint"/>). The semantic palette
/// (<see cref="BlockColorPalette"/>) stays the fallback for mod codes.
///
/// Thanks to this the map is coloured the way the block looks in the game (claystone is brown,
/// chert is dark brown, bauxite is reddish, rather than "one grey for all stones").
/// For mod blocks absent from the table, heuristics are enabled: stripping the domain and
/// the state (`-we`/`-ns`/`-free`/…), and carrying the rock colour over by the block "shape"
/// (stonebricks-X ← rock-X with a measured shape coefficient).
///
/// Besides the top-face colour, the same line carries metadata without which the in-game map cannot be
/// reproduced: the rainPermeable flag (the game colours the first NON-permeable block, so grass
/// and flowers are invisible on the map), the names of the climatic/seasonal LUTs, the texel samples
/// (ChunkMapLayer blends GetColor with a random texel from GetRandomColor at weight 0.6 —
/// hence the noise on the map) and, for a grass overlay, the base colour and the layer weight.
/// </summary>
public static class BlockColors
{
    private static readonly object _lock = new();
    private static Dictionary<string, int>? _table;          // code -> 0xRRGGBB
    private static Dictionary<string, BlockMapInfo>? _meta;
    private static Dictionary<string, (double R, double G, double B, int N)>? _shapeFactors;

    /// <summary>Block metadata for the in-game map: rain permeability, tint LUTs and
    /// texel samples (for the map noise). <see cref="Samples"/> is empty if there was no texture.
    ///
    /// For blocks with a grass overlay (BlockSoil/BlockSoilDeposit/BlockForestFloor) the colour is
    /// TWO colours: the grass layer (which is tinted by season/climate) and <see cref="GrassBase"/>
    /// (which receives NO tint), blended with the weight <see cref="GrassWeight"/>. That is how
    /// BlockWithGrassOverlay.GetColor/BlockForestFloor.GetColor work in the game: `none` has no weight,
    /// `normal` is 1.0, `sparse`/`verysparse` are 0.75/0.5, forestfloor is grass/7.</summary>
    public readonly record struct BlockMapInfo(bool RainPermeable, string? ClimateMap, string? SeasonMap,
        (byte R, byte G, byte B)[] Samples, (byte R, byte G, byte B)? GrassBase, float GrassWeight);

    /// <summary>How many codes the table has (0 — the resource failed to load).</summary>
    public static int Count => Table.Count;

    /// <summary>Whether the table is loaded (diagnostics/tests).</summary>
    public static bool Loaded => _table is not null;

    private static Dictionary<string, int> Table
    {
        get
        {
            if (_table is not null) return _table;
            EnsureLoaded();
            return _table!;
        }
    }

    private static void EnsureLoaded()
    {
        if (_table is not null) return;
        lock (_lock)
        {
            if (_table is not null) return;
            var map = new Dictionary<string, int>(StringComparer.Ordinal);
            var meta = new Dictionary<string, BlockMapInfo>(StringComparer.Ordinal);
            foreach (var line in ReadLines())
            {
                if (line.Length < 4 || line[0] == '#') continue;
                int eq = line.IndexOf('=');
                if (eq <= 0 || eq + 7 > line.Length) continue;
                if (!int.TryParse(line.AsSpan(eq + 1, 6), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int rgb))
                    continue;
                map[line.Substring(0, eq)] = rgb;
                if (line.Length > eq + 7 && line[eq + 7] == '|')
                    meta[line.Substring(0, eq)] = ParseMeta(line, eq + 8);
            }
            _table = map;
            _meta = meta;
        }
    }

    /// <summary>Parses the tail of a line: `rainPermeable|climate|season|sample,...[|base|weight]`.</summary>
    private static BlockMapInfo ParseMeta(string line, int from)
    {
        var parts = line[from..].Split('|');
        bool perm = parts.Length > 0 && parts[0] == "1";
        string? climate = parts.Length > 1 && parts[1] != "-" ? parts[1] : null;
        string? season = parts.Length > 2 && parts[2] != "-" ? parts[2] : null;
        (byte R, byte G, byte B)? baseColour = null;
        float weight = 0f;
        if (parts.Length > 5
            && parts[4].Length == 6
            && int.TryParse(parts[4], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int bv)
            && float.TryParse(parts[5], NumberStyles.Float, CultureInfo.InvariantCulture, out float w))
        {
            baseColour = ((byte)(bv >> 16), (byte)(bv >> 8), (byte)bv);
            weight = Math.Clamp(w, 0f, 1f);
        }
        (byte R, byte G, byte B)[] samples = Array.Empty<(byte, byte, byte)>();
        if (parts.Length > 3 && parts[3].Length > 0)
        {
            var raw = parts[3].Split(',');
            var list = new (byte R, byte G, byte B)[raw.Length];
            for (int i = 0; i < raw.Length; i++)
            {
                if (raw[i].Length == 6 &&
                    int.TryParse(raw[i], NumberStyles.HexNumber, CultureInfo.InvariantCulture, out int v))
                    list[i] = ((byte)(v >> 16), (byte)(v >> 8), (byte)v);
                else
                    list[i] = Unpack(0);
            }
            samples = list;
        }
        return new BlockMapInfo(perm, climate, season, samples, baseColour, weight);
    }

    private static IEnumerable<string> ReadLines()
    {
        var asm = typeof(BlockColors).GetTypeInfo().Assembly;
        // resource name: <RootNamespace>.BlockColors.txt
        string? name = null;
        foreach (var n in asm.GetManifestResourceNames())
            if (n.EndsWith("BlockColors.txt", StringComparison.Ordinal)) { name = n; break; }
        if (name is null) yield break;
        using var s = asm.GetManifestResourceStream(name);
        if (s is null) yield break;
        using var r = new StreamReader(s);
        string? line;
        while ((line = r.ReadLine()) is not null)
        {
            if (line.Length > 0 && line[^1] == '\r') line = line[..^1];
            if (line.Length > 0) yield return line;
        }
    }

    /// <summary>Block colour by code (case-insensitive, the `game:` domain may be left in).
    /// false — the code is not in the table (use the semantic palette).
    /// The hot path (an exact match) does not allocate: it is called for every pixel of the map.</summary>
    public static bool TryGet(string? code, out (byte r, byte g, byte b) rgb)
    {
        rgb = default;
        if (string.IsNullOrEmpty(code)) return false;
        var table = Table;
        if (table.Count == 0) return false;

        if (table.TryGetValue(code!, out int packed))     // exact match — no allocations
        {
            rgb = Unpack(packed);
            return true;
        }
        return TryGetSlow(code!, table, out rgb);
    }

    /// <summary>Map metadata (permeability, tint LUTs, samples). Case and domain
    /// are handled the same way as in <see cref="TryGet"/>; a mod code without an entry — false.</summary>
    public static bool TryGetMap(string? code, out BlockMapInfo info)
    {
        info = default;
        if (string.IsNullOrEmpty(code)) return false;
        EnsureLoaded();
        if (_meta!.TryGetValue(code!, out info)) return true;
        foreach (var variant in Variants(code!))
            if (_meta!.TryGetValue(variant, out info)) return true;
        return false;
    }

    /// <summary>Whether the block is permeable to rain (the game colours the map by the first NON-permeable block).
    /// The hot path is an exact match: a chunk scan calls this for every block.</summary>
    public static bool IsRainPermeable(string? code)
    {
        if (string.IsNullOrEmpty(code)) return false;
        if (_meta is not null && _meta.TryGetValue(code!, out var info)) return info.RainPermeable;
        if (TryGetMap(code, out var slow)) return slow.RainPermeable;
        // A mod block: we have no flag from the JSON — plants are considered permeable (see IsLikelyPlant).
        return BlockColorPalette.IsLikelyPlant(code);
    }

    private static bool TryGetSlow(string code, Dictionary<string, int> table, out (byte r, byte g, byte b) rgb)
    {
        rgb = default;
        foreach (var variant in Variants(code))
        {
            if (table.TryGetValue(variant, out int packed))
            {
                rgb = Unpack(packed);
                return true;
            }
            // "shape + rock": stonebricks-chert ← rock-chert × the stonebricks shape coefficient
            if (TryShapeFallback(table, variant, out packed))
            {
                rgb = Unpack(packed);
                return true;
            }
        }
        return false;
    }

    /// <summary>The code without the domain and without trailing states (`planks-aged-we` → `planks-aged`…),
    /// then the same one without the last token.</summary>
    private static IEnumerable<string> Variants(string code)
    {
        var c = code;
        int colon = c.IndexOf(':');
        if (colon >= 0 && colon + 1 < c.Length) c = c[(colon + 1)..];
        c = c.ToLowerInvariant();

        yield return c;
        // states (orientation/coverage/variant) — dropped one token at a time from the end
        var parts = c.Split('-');
        for (int take = parts.Length - 1; take >= 1; take--)
        {
            var trimmed = string.Join('-', parts, 0, take);
            if (IsStateToken(parts[take])) yield return trimmed;
        }
    }

    private static bool IsStateToken(string token) => token switch
    {
        "we" or "ns" or "ud" or "up" or "down" or "north" or "east" or "south" or "west" => true,
        "free" or "snow" or "snowed" or "empty" or "full" or "short" or "tall" or "thin" => true,
        "1" or "2" or "3" or "4" or "5" or "6" or "7" or "8" or "9" or "10" => true,
        _ => false,
    };

    /// <summary>A code of the form <c>{shape}-{rock}</c> where <c>rock-{rock}</c> is in the table:
    /// colour = the rock colour × the average shape coefficient (computed from the table).</summary>
    private static bool TryShapeFallback(Dictionary<string, int> table, string code, out int packed)
    {
        packed = 0;
        int dash = code.LastIndexOf('-');
        if (dash <= 0 || dash + 1 >= code.Length) return false;
        var shape = code[..dash];
        var rock = code[(dash + 1)..];
        if (!table.TryGetValue("rock-" + rock, out int rockRgb)) return false;
        if (!ShapeFactors.TryGetValue(shape, out var f) || f.N == 0) return false;

        var (r, g, b) = Unpack(rockRgb);
        packed = Pack(
            (byte)Math.Clamp(r * f.R, 0, 255),
            (byte)Math.Clamp(g * f.G, 0, 255),
            (byte)Math.Clamp(b * f.B, 0, 255));
        return true;
    }

    /// <summary>Average "shape/rock" coefficients measured from the table itself
    /// (for example stonebricks = 0.93 × rock). Computed once on first use.</summary>
    private static Dictionary<string, (double R, double G, double B, int N)> ShapeFactors
    {
        get
        {
            if (_shapeFactors is not null) return _shapeFactors;
            lock (_lock)
            {
                if (_shapeFactors is not null) return _shapeFactors;
                var table = Table;
                var acc = new Dictionary<string, (double R, double G, double B, int N)>(StringComparer.Ordinal);
                foreach (var kv in table)
                {
                    int dash = kv.Key.LastIndexOf('-');
                    if (dash <= 0) continue;
                    var shape = kv.Key[..dash];
                    var rock = kv.Key[(dash + 1)..];
                    if (!table.TryGetValue("rock-" + rock, out int rockRgb)) continue;
                    var (qr, qg, qb) = Unpack(kv.Value);
                    var (rr, rg, rb) = Unpack(rockRgb);
                    if (rr == 0 || rg == 0 || rb == 0) continue;
                    var cur = acc.TryGetValue(shape, out var v) ? v : (R: 0.0, G: 0.0, B: 0.0, N: 0);
                    acc[shape] = (cur.R + (double)qr / rr, cur.G + (double)qg / rg, cur.B + (double)qb / rb, cur.N + 1);
                }
                foreach (var key in new List<string>(acc.Keys))
                {
                    var v = acc[key];
                    if (v.N > 0) acc[key] = (v.R / v.N, v.G / v.N, v.B / v.N, v.N);
                }
                _shapeFactors = acc;
                return acc;
            }
        }
    }

    private static (byte r, byte g, byte b) Unpack(int packed)
        => ((byte)(packed >> 16), (byte)(packed >> 8), (byte)packed);

    private static int Pack(byte r, byte g, byte b) => (r << 16) | (g << 8) | b;
}
